import functools
import math

import torch

import fast_hadamard_transform


def get_hadK(n, transpose=False):
    hadK, K = None, None
    if n % 148 == 0:
        assert is_pow2(n // 148)
        K = 148
        hadK = get_had148().T if transpose else get_had148()
    elif n % 172 == 0:  # llama-2-7b up
        assert is_pow2(n // 172)
        K = 172
        hadK = get_had172().T if transpose else get_had172()
    elif n % 156 == 0:  # llama-1-30b 3x hidden
        assert is_pow2(n // 156)
        K = 156
        hadK = get_had156().T if transpose else get_had156()
    elif n % 140 == 0:  # llama-1-30b intermediate
        assert is_pow2(n // 140)
        K = 140
        hadK = get_had140().T if transpose else get_had140()
    elif n % 108 == 0:  # llama-1-13b intermediate
        assert is_pow2(n // 108)
        K = 108
        hadK = get_had108().T if transpose else get_had108()
    elif n % 60 == 0:  # llama-1-13b 3x hidden
        assert is_pow2(n // 60)
        K = 60
        hadK = get_had60().T if transpose else get_had60()
    elif n % 52 == 0:  # llama-1-13b 1x hidden
        assert is_pow2(n // 52)
        K = 52
        hadK = get_had52().T if transpose else get_had52()
    elif n % 44 == 0:
        assert is_pow2(n // 44)
        K = 44
        hadK = get_had44().T if transpose else get_had44()
    elif n % 36 == 0:
        assert is_pow2(n // 36)
        K = 36
        hadK = get_had36().T if transpose else get_had36()
    elif n % 28 == 0:
        assert is_pow2(n // 28)
        K = 28
        hadK = get_had28().T if transpose else get_had28()
    elif n % 40 == 0:
        assert is_pow2(n // 40)
        K = 40
        hadK = get_had40().T if transpose else get_had40()
    elif n % 20 == 0:
        assert is_pow2(n // 20)
        K = 20
        hadK = get_had20().T if transpose else get_had20()
    elif n % 12 == 0:
        assert is_pow2(n // 12)
        K = 12
        hadK = get_had12().T if transpose else get_had12()
    else:
        assert is_pow2(n)
        K = 1

    return hadK, K


def get_had_pow2(n, norm=True):
    assert is_pow2(n)
    had = torch.ones(1, 1)
    while had.shape[0] != n:
        had = torch.cat((torch.cat([had, had], 1), torch.cat([had, -had], 1)), 0)
        if norm:
            had /= math.sqrt(2)
    return had


def get_had(n, decompose=False):
    hads = []
    if is_pow2(n):
        if decompose:
            pow2 = int(math.log2(n))
            hadL_dim, hadR_dim = pow2 // 2, pow2 - pow2 // 2
            hadL = get_had_pow2(int(2**hadL_dim))
            hadR = get_had_pow2(int(2**hadR_dim))
            hads.extend([hadL, hadR])
        else:
            hads.append(get_had_pow2(n))
    else:
        hadR, K = get_hadK(n)
        hadR = hadR / torch.tensor(n).sqrt()
        if (n // K) > 1:
            hads.append(get_had_pow2(n // K, norm=False))
        hads.append(hadR)
    return hads


def _hadamard_transform(x: torch.Tensor, scale: float):
    return fast_hadamard_transform.hadamard_transform(x.contiguous(), scale=scale)


def _is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def _normalize_hadamard(had: torch.Tensor) -> torch.Tensor:
    had = had.clone()
    for idx in range(had.shape[1]):
        if had[0, idx] < 0:
            had[:, idx] *= -1
    for idx in range(had.shape[0]):
        if had[idx, 0] < 0:
            had[idx, :] *= -1
    return had


def _quadratic_residue_set_mod_prime(p: int) -> set[int]:
    return {pow(value, 2, p) for value in range(1, p)}


def _conference_matrix_paley_prime(order: int) -> torch.Tensor:
    q = order - 1
    if q % 4 != 1 or not _is_prime(q):
        raise ValueError(f"Paley type-II conference construction requires prime q ≡ 1 (mod 4), got q={q}.")
    residues = _quadratic_residue_set_mod_prime(q)
    matrix = torch.empty((order, order), dtype=torch.float64)
    matrix[0, :] = 1
    matrix[:, 0] = 1
    matrix[0, 0] = 0
    for row in range(1, order):
        for col in range(1, order):
            if row == col:
                matrix[row, col] = 0
            else:
                diff = (row - 1 - (col - 1)) % q
                matrix[row, col] = 1.0 if diff in residues else -1.0
    return matrix


def _hadamard_matrix_paley_type_ii_prime(order: int) -> torch.Tensor:
    conference = _conference_matrix_paley_prime(order // 2)
    block_zero = torch.tensor([[1.0, -1.0], [-1.0, -1.0]], dtype=torch.float64)
    block_pos = torch.tensor([[1.0, 1.0], [1.0, -1.0]], dtype=torch.float64)
    block_neg = torch.tensor([[-1.0, -1.0], [-1.0, 1.0]], dtype=torch.float64)
    rows = []
    for row in conference:
        blocks = []
        for value in row:
            scalar = int(value.item())
            if scalar == 0:
                blocks.append(block_zero)
            elif scalar > 0:
                blocks.append(block_pos)
            else:
                blocks.append(block_neg)
        rows.append(torch.cat(blocks, dim=1))
    return _normalize_hadamard(torch.cat(rows, dim=0))


def matmul_hadU(X, transpose=False):
    n = X.shape[-1]
    hadK, K = get_hadK(n, transpose)
    input = X.clone().view(-1, n, 1)
    output = input.clone()
    while input.shape[1] > K:
        input = input.view(input.shape[0], input.shape[1] // 2, 2, input.shape[2])
        output = output.view(input.shape)
        output[:, :, 0, :] = input[:, :, 0, :] + input[:, :, 1, :]
        output[:, :, 1, :] = input[:, :, 0, :] - input[:, :, 1, :]
        output = output.view(input.shape[0], input.shape[1], -1)
        (input, output) = (output, input)
    del output

    if K > 1:
        input = hadK.view(1, K, K).to(input) @ input

    return input.view(X.shape) / torch.tensor(n).sqrt()


def matmul_hadUt(X):
    return matmul_hadU(X, transpose=True)


def random_hadamard_matrix(size, device):
    Q = torch.randint(low=0, high=2, size=(size,)).to(torch.float64)
    Q = Q * 2 - 1
    Q = torch.diag(Q)
    return matmul_hadU(Q).to(device)


def hadamard_matrix(size, device):
    return matmul_hadU(torch.eye(size, dtype=torch.float64)).to(device)


def matmul_hadU_cuda(X, hadK, K):
    n = X.shape[-1]
    if K == 1:
        return _hadamard_transform(X, scale=1.0 / math.sqrt(n))
    input = X.contiguous().reshape(-1, K, n // K)
    input = _hadamard_transform(input, scale=1.0 / math.sqrt(n))
    input = hadK.to(input.device).to(input.dtype) @ input
    return input.reshape(X.shape)


def matmul_hadUt_cuda(X, hadK, K):
    return matmul_hadU_cuda(X, hadK, K)


def apply_exact_had_to_linear(module, had_dim=-1, output=False, R2=None):
    assert isinstance(module, torch.nn.Linear)
    in_features, out_features = module.in_features, module.out_features

    if had_dim != -1:
        assert is_pow2(had_dim), "Hadamard dimension must be a power of 2!"

    W_ = module.weight.data
    dtype = W_.dtype
    dev = W_.device
    transform_device = torch.device("cuda") if torch.cuda.is_available() else dev
    W_ = W_.float().to(transform_device)

    if had_dim == -1:
        if output:
            had_K, K = get_hadK(out_features)
            W_ = matmul_hadU_cuda(W_.t(), had_K, K).t()
        else:
            had_K, K = get_hadK(in_features)
            W_ = matmul_hadU_cuda(W_, had_K, K)
    else:
        hadK = hadamard_matrix(had_dim, transform_device).to(torch.float64)
        if R2 is not None:
            hadK = R2.to(device=transform_device, dtype=torch.float64)
        if output:
            W_ = W_.t()
            transposed_shape = W_.shape
            temp = W_.reshape(-1, transposed_shape[-1] // had_dim, had_dim)
            temp = temp.to(torch.float64) @ hadK
            W_ = temp.reshape(transposed_shape).t()
        else:
            init_shape = W_.shape
            temp = W_.reshape(-1, init_shape[-1] // had_dim, had_dim)
            temp = temp.to(torch.float64) @ hadK
            W_ = temp.reshape(init_shape)
    module.weight.data = W_.to(device=dev, dtype=dtype)


def is_pow2(n):
    return (n & (n - 1) == 0) and (n > 0)


# hadamard matrices for had12, had36.pal2, had52,will,
# # had60.pal, had108.pal, had140.pal, had156.will, had172.will:
# http://www.neilsloane.com/hadamard/index.html
